function strStr(haystack: string, needle: string): number {
  const n = haystack.length;
  const m = needle.length;

  // Перебираем все стартовые позиции, где needle ещё помещается целиком
  for (let start = 0; start + m <= n; start++) {
    let j = 0;

    // Сравниваем посимвольно, пока символы совпадают
    while (j < m && haystack[start + j] === needle[j]) {
      j++;
    }

    // Дошли до конца needle — вхождение найдено
    if (j === m) {
      return start;
    }
  }

  // Ни одна позиция не подошла
  return -1;
}

// Время: O((n - m + 1) · m) в худшем случае, на практике обычно близко к O(n)
// Память: O(1)
